// Original pt-BR foundation block. Install after the shared data modules, before app.js.
(()=>{
const choice=(q,options,answer,why)=>({type:'choice',q,options,answer,why});
const short=(q,answer,why)=>({type:'short',q,answer,why});
const listen=(text,options,answer,why)=>({type:'listen',text,options,answer,why,title:'Узнай на слух'});
const build=(answer,why)=>({type:'build',tokens:answer.split(/\s+/),answer,why,title:'Собери знакомую фразу'});
const units=[
{id:'oi',title:'Первое приветствие',goal:'Поздороваешься и узнаешь приветствие на слух. Начинаем с двух коротких слов.',minutes:'3–5 минут',
words:[['Oi!','Привет!'],['Olá!','Привет! / Здравствуйте!']],review:[],
parts:[['Oi!','короткое приветствие'],['Olá!','ещё один способ поздороваться']],
rule:'Oi и Olá — два обычных способа поздороваться в Бразилии. Oi звучит более неформально. В ответ на Oi можно сказать Oi или Olá. Это уже целая реплика: добавлять другие слова не нужно.',
reading:'Пишем латинскими буквами. Oi — две буквы O и i, которые произносятся слитно. В Olá знак над á показывает ударение на последнем слоге. Послушай запись: русская запись звуков может только приблизительно передать произношение.',
examples:[['Oi!','Привет!'],['Olá!','Привет! / Здравствуйте!']],
dialogue:[['Ана','Oi!','Привет!'],['Паулу','Olá!','Привет!']],
practice:[choice('Ана сказала Oi! Что можно ответить?', ['Нужно сначала назвать город','Можно тоже сказать Oi!'],1,'Приветствие можно повторить. Ты уже можешь начать разговор.'),listen('Olá!',['Человек здоровается','Человек называет своё имя'],0,'Olá! — приветствие. Здесь пока не нужно знать, как представиться.')],
tests:[choice('Что означает Oi!?',['Привет!','Меня зовут…'],0,'Oi! — привет!'),choice('Какое из изученных приветствий более неформальное?',['Olá!','Oi!'],1,'Oi — короткое неформальное приветствие.'),short('Напиши одно из двух приветствий по-португальски.',['oi','ola'],'Подойдут Oi! и Olá! Знаки препинания здесь не влияют на результат.')],
help:'Пока нужны только Oi! и Olá! Послушай одно слово и ответь таким же приветствием.'},
{id:'bem',title:'Спросить «Как дела?»',goal:'Спросишь, всё ли хорошо, и ответишь на тот же вопрос.',minutes:'5–8 минут',
words:[['tudo','всё'],['bem','хорошо'],['Tudo bem?','Как дела? / Всё хорошо?']],review:['oi'],
parts:[['tudo','всё'],['bem','хорошо'],['?','вопрос']],
rule:'Tudo bem буквально значит «всё хорошо». С вопросительной интонацией Tudo bem? — «Как дела?» или «Всё хорошо?». Как ответ Tudo bem. означает «Всё хорошо». Слова те же; меняются интонация и знак в конце. Отдельное слово для русского «как» здесь не требуется.',
reading:'В bem в конце нет отчётливого русского «м»: гласный звучит через нос. Не пытайся угадать его по буквам — сначала послушай и повтори целиком. Точка обозначает ответ, вопросительный знак — вопрос.',
examples:[['Tudo bem?','Как дела?'],['Tudo bem.','Всё хорошо.'],['Oi! Tudo bem?','Привет! Как дела?']],
dialogue:[['Ана','Oi! Tudo bem?','Привет! Как дела?'],['Паулу','Tudo bem.','Всё хорошо.']],
practice:[build('Tudo bem?','Всё хорошо? / Как дела?'),choice('Tudo bem? и Tudo bem. отличаются…',['порядком слов','интонацией и знаком в конце'],1,'В вопросе и ответе могут быть одни и те же слова.'),listen('Oi! Tudo bem?',['Приветствие и вопрос о делах','Только имя человека'],0,'Oi — привет; Tudo bem? — как дела?')],
tests:[choice('Что означает tudo?',['хорошо','всё'],1,'Tudo — всё.'),choice('Как ответить изученными словами, что всё хорошо?',['Tudo bem.','Olá!'],0,'Tudo bem. — всё хорошо.'),short('Допиши «Всё хорошо»: Tudo ___.',['bem'],'Tudo + bem = всё + хорошо.')],
help:'Раздели на два кусочка: tudo — всё, bem — хорошо. Со знаком вопроса спрашиваем, с точкой отвечаем.'},
{id:'voce',title:'Спросить в ответ «А у тебя?»',goal:'Поддержишь короткий разговор: ответишь и вернёшь вопрос.',minutes:'5–8 минут',
words:[['e','и / а'],['você','ты / вы'],['E você?','А ты? / А у тебя?']],review:['oi','bem'],
parts:[['Tudo bem.','Всё хорошо.'],['E','А'],['você?','у тебя?']],
rule:'После ответа Tudo bem. можно добавить E você? — «А у тебя?». E соединяет реплики и здесь переводится как «а». Você — обращение к одному человеку; по ситуации переводим «ты» или «вы». В этом занятии не нужны другие местоимения.',
reading:'В você буква ç передаёт звук «с», а ê указывает ударный гласный. Поэтому не читаем ç как «к». Фразу E você? лучше запомнить по записи целиком.',
examples:[['E você?','А у тебя?'],['Tudo bem. E você?','Всё хорошо. А у тебя?'],['Oi! Tudo bem?','Привет! Как дела?']],
dialogue:[['Ана','Oi! Tudo bem?','Привет! Как дела?'],['Паулу','Tudo bem. E você?','Всё хорошо. А у тебя?'],['Ана','Tudo bem.','Всё хорошо.']],
practice:[build('E você?','А у тебя?'),choice('Ты уже ответил Tudo bem. Что добавить, чтобы вернуть вопрос?',['E você?','Oi!'],0,'E você? возвращает тот же вопрос собеседнику.'),listen('Tudo bem, e você?',['Человек только здоровается','Человек отвечает и спрашивает в ответ'],1,'Tudo bem — ответ; e você? — вопрос в ответ.')],
tests:[choice('К кому обращено você в нашей реплике?',['К собеседнику','К говорящему'],0,'Você — ты / вы, обращение к собеседнику.'),choice('Как спросить «А у тебя?»',['Tudo bem.','E você?'],1,'E você? — а у тебя?'),short('Допиши вопрос в ответ: E ___?',['voce'],'Você пишется с ê. В этой проверке ответ без значка тоже принимается.')],
help:'Сначала ответь Tudo bem. Затем спроси E você? — а у тебя? Порядок из двух кусочков уже поддерживает разговор.'},
{id:'saudacoes',title:'Поздороваться утром, днём и вечером',goal:'Выберешь приветствие по времени суток и услышишь разницу.',minutes:'6–9 минут',
words:[['Bom dia!','Доброе утро!'],['Boa tarde!','Добрый день!'],['Boa noite!','Добрый вечер! / Спокойной ночи!']],review:['oi','bem','voce'],
parts:[['bom dia','доброе утро'],['boa tarde','добрый день'],['boa noite','добрый вечер / спокойной ночи']],
rule:'Утром обычно говорят Bom dia!, после полудня — Boa tarde!, вечером и ночью — Boa noite! Boa noite подходит и при встрече вечером, и при прощании на ночь. Bom и boa согласуются со следующим словом. Пока запоминаем эти три пары целиком, без таблицы родов.',
reading:'Dia — день, tarde — вторая половина дня, noite — вечер или ночь. В Бразилии произношение различается по регионам. Сначала узнавай целые фразы по аудио, а не пытайся вывести все звуки из русского написания.',
examples:[['Bom dia!','Доброе утро!'],['Boa tarde!','Добрый день!'],['Boa noite!','Добрый вечер! / Спокойной ночи!']],
dialogue:[['Ана, утром','Bom dia! Tudo bem?','Доброе утро! Как дела?'],['Паулу','Tudo bem. E você?','Всё хорошо. А у тебя?'],['Ана','Tudo bem.','Всё хорошо.']],
practice:[choice('Вы встретились утром. Выбери приветствие.',['Boa noite!','Bom dia!','Boa tarde!'],1,'Утром подходит Bom dia!'),listen('Boa tarde!',['Добрый вечер!','Доброе утро!','Добрый день!'],2,'Boa tarde! говорят после полудня.'),build('Boa noite!','Добрый вечер!')],
tests:[choice('После полудня ты заходишь в магазин. Что скажешь?',['Boa tarde!','Bom dia!','Boa noite!'],0,'После полудня — Boa tarde!'),choice('Какое приветствие подходит вечером?',['Bom dia!','Boa noite!','Boa tarde!'],1,'Вечером — Boa noite!'),short('Допиши утреннее приветствие: Bom ___!',['dia'],'Bom dia! — доброе утро!')],
help:'Утро — Bom dia. День после полудня — Boa tarde. Вечер и ночь — Boa noite. Oi тоже остаётся удобным неформальным приветствием.'},
{id:'nome',title:'Назвать своё имя',goal:'Представишься одной простой фразой и поймёшь её устройство.',minutes:'6–9 минут',
words:[['eu','я'],['sou','есть / являюсь, форма для «я»']],review:['oi','bem','voce','saudacoes'],
parts:[['Eu','я'],['sou','есть / являюсь'],['Ana','имя Ана']],
rule:'Eu sou Ana. — «Я Ана». Eu указывает, кто говорит, sou связывает говорящего с именем. По-русски «я есть Ана» обычно не говорят; в португальской фразе sou оставляем. Sou — форма глагола ser для eu. Глагол — слово, которое может обозначать действие или состояние; здесь он связывает человека с именем. Пока достаточно одной формы.',
reading:'В sou сочетание ou произносится слитно; послушай запись. Ana и Paulo — имена наших собеседников, они не требуют перевода. Своё имя можно написать привычными латинскими буквами.',
examples:[['Eu sou Ana.','Я Ана.'],['Eu sou Paulo.','Я Паулу.'],['Oi! Eu sou Ana.','Привет! Я Ана.']],
dialogue:[['Ана','Oi! Eu sou Ana.','Привет! Я Ана.'],['Паулу','Olá! Eu sou Paulo.','Привет! Я Паулу.']],
practice:[build('Eu sou Ana.','Я Ана.'),choice('Что меняем в Eu sou Ana., чтобы назвать себя?',['Убираем sou','Заменяем Ana своим именем'],1,'Eu sou остаётся, после него ставим своё имя.'),listen('Eu sou Ana.',['Человек представляется','Человек спрашивает, как дела'],0,'Eu sou Ana. — я Ана.')],
tests:[choice('Что означает eu?',['я','ты / вы'],0,'Eu — я, тот, кто говорит.'),choice('Как построить изученную фразу с именем?',['Eu + имя + sou','Eu + sou + имя'],1,'Eu sou Ana. — я Ана.'),short('Допиши «Я Ана»: Eu ___ Ana.',['sou'],'С eu используем sou: Eu sou Ana.')],
personal:'Представься: напиши Eu sou и своё имя. Например: Eu sou Ana.',
help:'Три кусочка: Eu — я; sou — являюсь; дальше твоё имя. Не нужно знать все формы ser, чтобы представиться.'},
{id:'chama',title:'Спросить имя собеседника',goal:'Поймёшь вопрос об имени и узнаешь ещё один способ представиться.',minutes:'8–12 минут',
words:[['Como você se chama?','Как тебя зовут? / Как вас зовут?'],['Meu nome é…','Меня зовут…']],review:['oi','bem','voce','nome'],
parts:[['Como','как'],['você','ты / вы'],['se chama','зовёшься / называетесь'],['meu','мой'],['nome','имя'],['é','есть / является']],
rule:'Como você se chama? буквально: «Как ты называешься?» Se chama здесь учим как цельный кусочек «зовёшься». Можно ответить уже знакомым Eu sou Ana. Ещё один ответ: Meu nome é Ana. — буквально «Моё имя — Ана». Meu = мой, nome = имя, é = есть. É связывает имя с его названием, sou употребляли с eu. Не меняем их местами.',
reading:'В слове nome безударная конечная e во многих бразильских вариантах звучит близко к «и». В é значок важен для написания и произношения. Не нужно учить все правила чтения сразу: повтори знакомую фразу по записи.',
examples:[['Como você se chama?','Как тебя зовут?'],['Meu nome é Paulo.','Меня зовут Паулу.'],['Eu sou Ana.','Я Ана.']],
dialogue:[['Ана','Oi! Eu sou Ana. Como você se chama?','Привет! Я Ана. Как тебя зовут?'],['Паулу','Meu nome é Paulo.','Меня зовут Паулу.']],
practice:[choice('Тебя спросили Como você se chama? Что подойдёт?',['Eu sou Ana.','Boa noite!'],0,'На вопрос об имени можно ответить уже знакомым Eu sou + имя.'),build('Meu nome é Paulo.','Меня зовут Паулу.'),listen('Como você se chama?',['Вопрос о времени','Вопрос об имени'],1,'Como você se chama? — как тебя зовут?')],
tests:[choice('Как спросить имя?',['E você?','Como você se chama?'],1,'Como você se chama? — как тебя зовут?'),choice('Что означает nome?',['имя','всё'],0,'Nome — имя.'),short('Допиши «Меня зовут Ана»: Meu nome ___ Ana.',['e'],'Meu nome é Ana. Здесь é — есть / является.')],
personal:'Ответь своим именем: Eu sou … или Meu nome é …',
help:'Вопрос об имени: Como você se chama? Для ответа выбери одну форму: Eu sou + имя или Meu nome é + имя. Обе подходят.'},
{id:'repetir',title:'Попросить повторить',goal:'Сможешь остановить непонятную речь и попросить повторить.',minutes:'6–9 минут',
words:[['Não entendi.','Не понял / не поняла.'],['Pode repetir?','Можете повторить?'],['por favor','пожалуйста, в просьбе']],review:['oi','bem','voce','nome','chama'],
parts:[['não','не'],['entendi','понял / поняла'],['pode','можете'],['repetir','повторить'],['por favor','пожалуйста']],
rule:'Не понял собеседника? Скажи Não entendi. Затем Pode repetir? — «Можете повторить?» Для вежливости добавь por favor: Pode repetir, por favor? Não ставим перед entendi. После pode используем repetir в начальной форме. Это две готовые полезные реплики: разбирать все прошедшие времена сейчас не нужно.',
reading:'В não знак ~ обозначает носовой гласный; слушай целое слово. Русское «пожалуйста» в просьбе — por favor. Здесь entendi подходит человеку любого пола: не меняем окончание по русскому образцу.',
examples:[['Não entendi.','Не понял / не поняла.'],['Pode repetir?','Можете повторить?'],['Pode repetir, por favor?','Можете повторить, пожалуйста?']],
dialogue:[['Ана','Como você se chama?','Как тебя зовут?'],['Паулу','Não entendi. Pode repetir, por favor?','Не понял. Можете повторить, пожалуйста?'],['Ана','Como você se chama?','Как тебя зовут?'],['Паулу','Eu sou Paulo.','Я Паулу.']],
practice:[build('Pode repetir?','Можете повторить?'),choice('Ты не расслышал вопрос. Что поможет?',['Делать вид, что понял','Сказать Não entendi. Pode repetir?'],1,'Просьба повторить помогает продолжить разговор.'),listen('Pode repetir, por favor?',['Просьба повторить','Ответ об имени'],0,'Pode repetir, por favor? — можете повторить, пожалуйста?')],
tests:[choice('Что означает Não entendi.?',['Всё хорошо','Не понял / не поняла'],1,'Não entendi. — не понял / не поняла.'),choice('Как попросить повторить?',['Pode repetir?','Eu sou Ana.'],0,'Pode repetir? — можете повторить?'),short('Допиши просьбу: Pode ___?',['repetir'],'После pode используем repetir — повторить.')],
help:'Не нужно понимать всё. Назови проблему: Não entendi. Затем попроси: Pode repetir? Это уже успешное действие в разговоре.'},
{id:'primeiro-dialogo',title:'Мой первый разговор',goal:'Соединишь знакомые реплики в небольшой разговор. Новых слов и правил нет.',minutes:'8–12 минут',words:[],review:['oi','bem','voce','saudacoes','nome','chama','repetir'],
parts:[['Oi!','приветствие'],['Tudo bem?','вопрос о делах'],['E você?','встречный вопрос'],['Eu sou…','представление'],['Pode repetir?','помощь, если не понял']],
rule:'Короткий разговор можно собрать из знакомых кусочков: поздороваться → спросить о делах → ответить → представиться → узнать имя. Если что-то непонятно, попроси повторить. Не нужно говорить все выученные фразы сразу: выбирай то, что подходит к реплике собеседника.',
reading:'Сначала послушай отдельные реплики. Потом закрой перевод и попробуй понять последовательность. Если забыл слово, открой подсказку: это повторение, а не экзамен.',
examples:[['Oi! Tudo bem?','Привет! Как дела?'],['Tudo bem. E você?','Всё хорошо. А у тебя?'],['Eu sou Ana.','Я Ана.']],
dialogue:[['Ана','Oi! Tudo bem?','Привет! Как дела?'],['Паулу','Tudo bem. E você?','Всё хорошо. А у тебя?'],['Ана','Tudo bem. Eu sou Ana. Como você se chama?','Всё хорошо. Я Ана. Как тебя зовут?'],['Паулу','Eu sou Paulo.','Я Паулу.']],
practice:[listen('Como você se chama?',['Просят повторить','Спрашивают имя','Приветствуют утром'],1,'Нужно ответить именем, например Eu sou Ana.'),build('Tudo bem. E você?','Всё хорошо. А у тебя?'),choice('Собеседник сказал Não entendi. Pode repetir? Что сделать?',['Повторить свою реплику','Сменить тему и не отвечать'],0,'Он попросил повторить. Можно сказать ту же фразу ещё раз спокойнее.')],
tests:[choice('Вечером ты начинаешь разговор. Выбери подходящую реплику.',['Bom dia!','Boa noite!'],1,'Вечером — Boa noite!'),choice('Тебя спросили Como você se chama? Выбери ответ.',['Meu nome é Paulo.','Tudo bem.'],0,'Здесь спрашивают имя, не о самочувствии.'),choice('Собеседник спросил Tudo bem? Как ответить и вернуть вопрос?',['Eu sou Ana.','Tudo bem. E você?'],1,'Ответ о делах, затем встречный вопрос.'),short('Попроси повторить двумя словами.',['pode repetir'],'Pode repetir? — можете повторить?'),short('Допиши: Eu ___ Ana.',['sou'],'Eu sou Ana. — я Ана.')],
personal:'Представь, что знакомишься с соседом. Напиши 2–4 реплики из знакомых слов: приветствие, вопрос о делах и представление. Можно использовать своё имя.',
help:'Начни с Oi! Потом выбери знакомый вопрос. Для имени — Eu sou или Meu nome é. Здесь не нужны названия города, гор или предметов.'}
];
const byId=Object.fromEntries(units.map((u,i)=>[u.id,{...u,number:i+1,version:2}]));
const course=window.BoraCourses[0],previous=course.lessons;
for(const u of Object.values(byId)){
  const old=previous.find(l=>l.id===u.id);
  u.dictionary=[...u.review.flatMap(id=>byId[id].words),...u.words];
  const lesson={...old,id:u.id,title:u.title,module:'С самого нуля',topic:u.title,scene:u.goal,idea:u.rule,examples:u.examples,quiz:u.tests.filter(q=>q.type==='choice').slice(0,2).map(q=>[q.q,q.options,q.answer,q.why]),write:[u.tests.find(q=>q.type==='short').q,u.tests.find(q=>q.type==='short').answer,u.tests.find(q=>q.type==='short').why],mission:u.personal||u.goal,level:'Старт',difficulty:'easy',beginnerVersion:2};
  u.lesson=lesson;
  window.BoraLessonContent[u.id]={rule:u.rule,words:u.words,model:[u.dialogue.map(row=>row[1]).join(' '),u.dialogue.map(row=>row[2]).join(' ')],checks:['Я выполнил просьбу задания','Я использовал знакомые фразы','Я сравнил свой ответ с образцом'],write:u.personal};
  window.BoraKit.rules[u.id]=[u.parts,u.rule,u.reading,'greeting'];
  window.BoraKit.readingRU[u.id]=u.dialogue.map(row=>row[0]+': '+row[2]).join('\n');
  window.BoraComfort.simple[u.id]=u.help;
  if(!window.BoraLessonPhotos[u.id])window.BoraLessonPhotos[u.id]=window.BoraLessonPhotos[({bem:'cafe',voce:'familia',saudacoes:'horas',chama:'telefone',repetir:'poder','primeiro-dialogo':'conversa'})[u.id]]||window.BoraLessonPhotos.oi;
}
previous.forEach((l,i)=>{l.difficulty=i<10?'easy':i<20?'medium':'hard';});
course.modules=[{title:'С самого нуля',lessons:Object.keys(byId)},...course.modules.map(m=>({...m,lessons:m.lessons.filter(id=>!byId[id])})).filter(m=>m.lessons.length)];
course.lessons=[...Object.values(byId).map(u=>u.lesson),...previous.filter(l=>!byId[l.id])];
function complete(user,lesson){const r=user.courseProgress?.['pt/'+lesson.id];return byId[lesson.id]?r?.guided?.version===2&&!!r.guided.finishedAt:!!r?.done}
window.BoraBeginner={version:2,units:byId,complete};
})();
